 @Test void approvedCostRequiresOpenFinancialPeriod(){waiting();long id=cost();LocalDate start=LocalDate.now().withDayOfMonth(1);f.db.sql("INSERT INTO accounting_periods(property_id,period_code,start_date,end_date,status) VALUES(:property,:code,:start,:end,'CLOSED')").param("property",property).param("code",start.toString().substring(0,7)).param("start",start).param("end",start.plusMonths(1).minusDays(1)).update();assertThatThrownBy(()->f.run(()->service.reviewCost(f.owner,id,new Decision(0,true,"Closed period")))).isInstanceOf(RuntimeException.class);assertThat(rows(read(f.owner,"costs")).getFirst().get("expense_id")).isNull();}
